package com.gomgomapps.math.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class DivisionNotationsTest {
 @Test public void threeVisibleFormsHaveSameOperandsAndExactValue(){for(int style=0;style<3;style++)for(int a:List.of(0,1,42,999999,1000000))for(int b:List.of(1,6,99)){Question q=DivisionNotations.make(a,b,style);q.answers=new String[]{"poison"};assertTrue(DivisionNotations.check(q,List.of(""+a,""+b,Rational.of(a,b).toString())).correct());assertEquals(0,DivisionNotations.check(q,List.of(""+(a+1),""+b,Rational.of(a,b).toString())).index);assertFalse(q.studyGuide.transfer);assertEquals(5,q.studyGuide.frames.size());assertEquals(""+a,q.studyGuide.frames.get(0).expected);assertEquals(""+b,q.studyGuide.frames.get(1).expected);}}
 @Test public void remainderIsExactAndOperandOrderMatters(){Question q=DivisionNotations.make(43,6,2);assertTrue(DivisionNotations.check(q,List.of("43","6","43/6")).correct());assertFalse(DivisionNotations.check(q,List.of("43","6","7")).correct());assertEquals(0,DivisionNotations.check(q,List.of("6","43","6/43")).index);Question finite=DivisionNotations.make(45,6,1);assertTrue(DivisionNotations.check(finite,List.of("45","6","7.5")).correct());}
 @Test public void malformedGeometryAndUndefinedDivisionAreRejected(){Question q=DivisionNotations.make(43,6,1);for(double invalid:new double[]{0,-1,100,Double.NaN}){q.diagram.values[1]=invalid;assertNull(DivisionNotations.read(q));}q=DivisionNotations.make(43,6,2);q.diagram.values[2]=3;assertNull(DivisionNotations.read(q));q=DivisionNotations.make(43,6,0);assertEquals(Checker.Status.INPUT_NEEDED,DivisionNotations.check(q,List.of("43","6","1/0")).status);}
 @Test public void actualPipelineThreeStylesFreshAndPublicHelp(){var limits=GlobalCurriculum.limits("na-nied-primary-2024-v1",DivisionNotations.ID,6);Generator generator=new Generator(new Random(259));List<String> recent=new ArrayList<>();Set<Integer> styles=new HashSet<>();for(int i=0;i<150;i++){Question q=generator.next(DivisionNotations.ID,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=DivisionNotations.read(q);styles.add(v.notation());String signature=q.signature();q.answers=new String[]{"poison"};assertEquals(signature,q.signature());assertTrue(new Checker().check(q,List.of(),List.of(""+v.dividend(),""+v.divisor(),Rational.of(v.dividend(),v.divisor()).toString())).correct());HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertEquals(5,h.size());assertTrue(h.step(0).accepts(""+v.dividend()));assertTrue(h.step(1).accepts(""+v.divisor()));}assertEquals(Set.of(0,1,2),styles);}
 @Test public void allSmallDiagramConditionsFreshThenOldest(){var limits=new CurriculumLimits("minGiven=0;maxGiven=1;contextDivisorMinimum=1;contextDivisorMaximum=2");Generator generator=new Generator(new Random(260));List<String> recent=new ArrayList<>();for(int i=0;i<12;i++){Question q=generator.next(DivisionNotations.ID,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());}assertEquals(recent.get(0),generator.next(DivisionNotations.ID,recent,false,limits).signature());}
}
